import{_ as e,c as a,o as t,a2 as i}from"./chunks/framework.CIiVzG-O.js";const Z=JSON.parse('{"title":"常见问题","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/guide/faq.md","filePath":"zh-CN/guide/faq.md","lastUpdated":1793163976000}'),r={name:"zh-CN/guide/faq.md"};function s(n,p,o,u,c,l){return t(),a("div",null,[...p[0]||(p[0]=[i('<h1 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h1><p>问：什么是 NueZip？</p><p>答：NueZip 是一款为 macOS 打造的专业归档管理器，支持 RAR、ZIP、7-Zip、TAR、GZIP 和 BZIP2 等多种归档格式的压缩与解压。</p><p>问：支持哪些 macOS 版本？</p><p>答：NueZip 需要 macOS 14 Sonoma 或更高版本，并针对 Apple Silicon（M 系列）芯片进行了优化。</p><p>问：如何下载并安装 NueZip？</p><p>答：从 <a href="https://apps.apple.com/app/id6785846417" target="_blank" rel="noreferrer">Mac App Store</a>（推荐）下载，或从 <a href="https://github.com/nuezip/nuezip/releases" target="_blank" rel="noreferrer">GitHub Releases</a> 获取最新版本。</p><p>问：NueZip 免费吗？</p><p>答：NueZip 提供带有核心功能的免费试用。一次性购买可解锁完整功能集，包括批量操作、归档修复和高级加密。</p><p>问：支持哪些格式？</p><p>答：<strong>读取</strong>：RAR、ZIP、7-Zip、TAR、GZIP、BZIP2、XZ、Zstandard<br><strong>写入（压缩）</strong>：ZIP、7-Zip、TAR、GZIP、BZIP2、XZ、Zstandard<br> 完整的格式矩阵请参阅 <a href="/zh-CN/guide/introduction.html">简介</a>。</p><p>问：NueZip 可以创建 RAR 归档吗？</p><p>答：不可以。NueZip 可以 <strong>读取</strong> RAR 归档（包括多卷和已修复的归档），但由于许可限制，不支持 RAR 压缩。</p><p>问：NueZip 对机密文件安全吗？</p><p>答：是的。NueZip 完全离线运行。所有操作都在你的 Mac 本地运行。支持使用 AES-256 加密来保护带密码的 ZIP 归档。</p><p>问：NueZip 会把我的文件上传到云端吗？</p><p>答：不会。NueZip 是一款完全离线的应用。你的文件永远不会被上传到任何地方。压缩或解压都不需要互联网连接。</p><p>问：如何更新应用？</p><p>答：通过 Mac App Store（自动）更新，或从 GitHub Releases 下载最新版本。</p><p>问：如何报告 Bug 或请求功能？</p><p>答：在 <a href="https://github.com/nuezip/nuezip/issues" target="_blank" rel="noreferrer">GitHub 仓库</a> 上提交 issue。请包含你的 macOS 版本、NueZip 版本以及复现步骤。</p><p>问：日志和数据存储在哪里？</p><p>答：对于沙盒（App Store）构建版本：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/Library/Containers/com.w3cub.nuezip/Data/Library/Application Support/com.w3cub.nuezip/</span></span></code></pre></div><p>开发构建版本可能会将日志写入控制台。</p><p>如果你需要更多解答，请在仓库中提交 issue 或查阅完整文档。</p>',26)])])}const h=e(r,[["render",s]]);export{Z as __pageData,h as default};
